struct manager_ctx {
    ev_io io;
    int fd;
    int fast_open;
    int reuse_port;
    int verbose;
    int mode;
    char *password;
    char *key;
    char *timeout;
    char *method;
    char *iface;
    char *acl;
    char *user;
    char *plugin;
    char *plugin_opts;
    char *manager_address;
    char **hosts;
    int host_num;
    char **nameservers;
    int nameserver_num;
    int mtu;
    int ipv6first;
#ifdef HAVE_SETRLIMIT
    int nofile;
#endif
}

struct server {
    char port[8];
    char password[128];
    char fast_open[8];
    char *mode;
    char *method;
    char *plugin;
    char *plugin_opts;
    uint64_t traffic;
}

